    "Genadijs": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Klāvs Siliņš’s dictionary (1990) connects Genadijs with the source word Greek gennadas, meaning noble.",
          "The dictionary gives the following historical record: Riga, 1923; calendar 1889. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date."
        ],
        "lv": [
          "Klāva Siliņa vārdnīca (1990) Genadijs saista ar grieķu vārdu gennadas, kura nozīme ir dižciltīgs.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Rīga, 1923; kalendārā 1889. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu."
        ],
        "ru": [
          "Словарь Клавса Силиньша (1990) связывает Genadijs с греческим словом gennadas со значением «благородный».",
          "Словарь приводит следующую историческую запись: Рига, 1923; календарь 1889. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени."
        ],
        "lt": [
          "Klāvo Siliņšo žodynas (1990) Genadijs sieja su graikų žodžiu gennadas, kurio reikšmė — kilmingas.",
          "Žodynas pateikia tokį istorinį įrašą: Ryga, 1923; kalendoriuje 1889. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo."
        ],
        "et": [
          "Klāvs Siliņši sõnastik (1990) seostab nime Genadijs kreeka sõnaga gennadas, tähendusega suursugune.",
          "Sõnastik annab järgmise ajaloolise kirje: Riia, 1923; kalendris 1889. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist."
        ]
      }
    },
    "Sanda": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Klāvs Siliņš’s dictionary (1990) explicitly refers Sanda to Aleksandra. This records a relationship between name forms; it does not by itself resolve the family’s more distant word origin.",
          "The dictionary gives the following historical record: Vidzeme, fourth quarter of the nineteenth century; calendar 1932. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date. The dates belong to the shared Sanda / Sande entry, not to independently checked records for each spelling."
        ],
        "lv": [
          "Klāva Siliņa vārdnīca (1990) Sanda tieši saista ar Aleksandra. Tā ir vārda formu saikne, kas pati par sevi nenosaka saimes tālāko leksisko izcelsmi.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Vidzeme, 19. gadsimta ceturtais ceturksnis; kalendārā 1932. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu. Datumi attiecas uz kopīgo šķirkli Sanda / Sande, nevis atsevišķi pārbaudītiem katras rakstības ierakstiem."
        ],
        "ru": [
          "Словарь Клавса Силиньша (1990) прямо отсылает от Sanda к Aleksandra. Это связь форм имени; сама по себе она не устанавливает дальнее словарное происхождение всей группы.",
          "Словарь приводит следующую историческую запись: Видземе, четвёртая четверть XIX века; календарь 1932. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени. Даты относятся к общей статье Sanda / Sande, а не к отдельно проверенным записям каждого написания."
        ],
        "lt": [
          "Klāvo Siliņšo žodynas (1990) Sanda tiesiogiai sieja su Aleksandra. Tai vardo formų ryšys, savaime nenustatantis tolimesnės visos grupės leksinės kilmės.",
          "Žodynas pateikia tokį istorinį įrašą: Vidžemė, XIX amžiaus ketvirtasis ketvirtis; kalendoriuje 1932. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo. Datos priklauso bendram Sanda / Sande straipsniui, o ne atskirai patikrintiems kiekvienos rašybos įrašams."
        ],
        "et": [
          "Klāvs Siliņši sõnastik (1990) seob nime Sanda otseselt kujuga Aleksandra. See dokumenteerib nimekujude seose, lahendamata iseenesest nimepere kaugemat sõnalist päritolu.",
          "Sõnastik annab järgmise ajaloolise kirje: Liivimaa (Vidzeme), 19. sajandi neljas veerand; kalendris 1932. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist. Daatumid kuuluvad ühise Sanda / Sande artikli juurde, mitte iga kirjapildi eraldi kontrollitud kirjete juurde."
        ]
      }
    },
