    "Medards": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Klāvs Siliņš’s dictionary (1990) explains Medards through the Old High German components macht + hart. Their meanings are, respectively: power; strong.",
          "The dictionary gives the following historical record: Riga, 1873; calendar 1767. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date. The dates belong to the shared Medards / Medarts entry, not to independently checked records for each spelling."
        ],
        "lv": [
          "Klāva Siliņa vārdnīca (1990) Medards skaidro ar senaugšvācu sastāvdaļām macht + hart. To nozīmes attiecīgi ir: vara; stiprs.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Rīga, 1873; kalendārā 1767. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu. Datumi attiecas uz kopīgo šķirkli Medards / Medarts, nevis atsevišķi pārbaudītiem katras rakstības ierakstiem."
        ],
        "ru": [
          "Словарь Клавса Силиньша (1990) объясняет Medards через древневерхненемецкие компоненты macht + hart. Их значения соответственно: власть; сильный.",
          "Словарь приводит следующую историческую запись: Рига, 1873; календарь 1767. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени. Даты относятся к общей статье Medards / Medarts, а не к отдельно проверенным записям каждого написания."
        ],
        "lt": [
          "Klāvo Siliņšo žodynas (1990) Medards aiškina senosios vokiečių aukštaičių kalbos dėmenimis macht + hart. Jų reikšmės atitinkamai: galia; stiprus.",
          "Žodynas pateikia tokį istorinį įrašą: Ryga, 1873; kalendoriuje 1767. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo. Datos priklauso bendram Medards / Medarts straipsniui, o ne atskirai patikrintiems kiekvienos rašybos įrašams."
        ],
        "et": [
          "Klāvs Siliņši sõnastik (1990) seletab nime Medards vanakõrgsaksa osadega macht + hart. Nende tähendused on vastavalt: võim; tugev.",
          "Sõnastik annab järgmise ajaloolise kirje: Riia, 1873; kalendris 1767. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist. Daatumid kuuluvad ühise Medards / Medarts artikli juurde, mitte iga kirjapildi eraldi kontrollitud kirjete juurde."
        ]
      },
      "calendar_entry_year": 1767
    },
