          "Vārdnīca dod šādu vēsturisku ierakstu: Kurzeme, 1638. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu. Vēsturiskā oriģinālieraksta rakstība un konteksts nav neatkarīgi pārbaudīti; tā datums nepierāda mūsdienu ortogrāfiju."
